SELECT
  MAX(
    2 * 6371.0 * ASIN(
      SQRT(
        POWER(SIN(RADIANS( (CAST((ar.coordinates) AS TEXT) -- will parse point as "(lon,lat)"
          ) /* placeholder */ )), 2)
      )
    )
  ) AS max_distance_km
FROM flights f
JOIN airports_data ad ON f.departure_airport = ad.airport_code
JOIN airports_data ar ON f.arrival_airport = ar.airport_code
WHERE (json_extract(ad.city, '$.en') = 'Abakan') OR (json_extract(ar.city, '$.en') = 'Abakan')
